CREATE TABLE IF NOT EXISTS data_sources (
  id text PRIMARY KEY,
  name text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('filings', 'prices', 'macro', 'news', 'fundamentals', 'reference', 'regulatory', 'other')),
  licence_class text NOT NULL CHECK (licence_class IN ('public_gov', 'public_attrib', 'internal_only', 'licensed', 'unknown')),
  display_allowed boolean NOT NULL DEFAULT false,
  redistribution_allowed boolean NOT NULL DEFAULT false,
  terms_url text,
  terms_checked_on date,
  attribution_text text,
  rate_limit_note text,
  daily_cap integer CHECK (daily_cap >= 0),
  monthly_cost_cap_eur numeric(10,2) CHECK (monthly_cost_cap_eur >= 0),
  notes text NOT NULL DEFAULT '',
  CHECK (licence_class <> 'unknown' OR (display_allowed = false AND redistribution_allowed = false))
);

ON CONFLICT (id) DO NOTHING;
